import sys

def solve():
    data = sys.stdin.read().split()
    N, M = int(data[0]), int(data[1])
    S = data[2]
    MOD = 998244353

    size = 1 << N
    # Precompute transitions
    trans = [[0]*26 for _ in range(size)]
    for V in range(size):
        r = [0]*(N+1)
        for i in range(N):
            r[i+1] = r[i] + ((V >> i) & 1)
        for c in range(26):
            ch = chr(ord('a') + c)
            r2 = [0]*(N+1)
            for i in range(1, N+1):
                if S[i-1] == ch:
                    r2[i] = r[i-1] + 1
                else:
                    v = r[i]
                    if r2[i-1] > v:
                        v = r2[i-1]
                    r2[i] = v
            Vp = 0
            for i in range(N):
                if r2[i+1] - r2[i] == 1:
                    Vp |= (1 << i)
            trans[V][c] = Vp

    f = [0]*size
    f[0] = 1
    for _ in range(M):
        g = [0]*size
        for V in range(size):
            fv = f[V]
            if fv == 0:
                continue
            tv = trans[V]
            for c in range(26):
                Vp = tv[c]
                g[Vp] = (g[Vp] + fv) % MOD
        f = g

    ans = [0]*(N+1)
    for V in range(size):
        k = bin(V).count('1')
        ans[k] = (ans[k] + f[V]) % MOD
    print(*ans)

solve()
